-- 全屏黑幕


---@class DreamSpace_FullScreen
---@field fullScreenImage              UnityEngine.UI.Image
local DreamSpace_FullScreen = Class('DreamSpace_FullScreen')
-- 外部调用时使用:
-- local DreamSpace_FullScreen = import('Game.DreamSpace.Level1.Story.DreamSpace_FullScreen')

-- ========================================================


local DreamlandUtils = import('Game.UI.FightReady.UIDreamland.DreamlandUtils')



--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程



local ETCJoystick = import('Game.Behaviours.ETCJoystick')
local PiecesCollection = import('Game.DreamSpace.PiecesCollection.PiecesCollection')

---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local QuestLvl1 = import('Game.DreamSpace.Level1.Quest.QuestLvl1')

---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')


local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Physics = CS.UnityEngine.Physics
local LayerMask = CS.UnityEngine.LayerMask
local Image = CS.UnityEngine.UI.Image
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3
local Mathf = CS.UnityEngine.Mathf

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils
local LuaParameters = CS.Engine.Modules.LuaParameters

local ElectricalTrigger = CS.ElectricalSystem.ElectricalTrigger
local OnOff = CS.Game.OnOff


-- ========================================================

local currentInstance = nil

-- ========================================================


function DreamSpace_FullScreen:__init()
    self.controller = nil
    self.co = nil   -- 发送携程请求

end


function DreamSpace_FullScreen:__delete()
    self.co = nil
end


function DreamSpace_FullScreen:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 DreamSpace_FullScreen 实例" )
    end 
end



function DreamSpace_FullScreen:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    assert( self.fullScreenImage )
    KTool.SetActive( self.fullScreenImage.gameObject, true )
    self.fullScreenImage.enabled = true 

    self.tgtAlpha = 0
    self.approachSpeed = 1.0
    self.isDirty = false
    self.tmpColor = Color( 0,0,0,0 )

    self.fullScreenImage.color = self.tmpColor
end



function DreamSpace_FullScreen:OnDestroy()
    currentInstance = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function DreamSpace_FullScreen.WaitInstance()
    -- 只等待有限帧
    for i=1,500 do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    assert( isNotNull(currentInstance), "始终没能等到 DreamSpace_FullScreen 实例化, 请检查场景" )
end


function DreamSpace_FullScreen.GetInstance()
    return currentInstance
end


function DreamSpace_FullScreen:Update()
    if self.isDirty == false  then 
        return
    end 

    -- 足够接近就停止
    if  DreamSpaceLuaUtils.CloseEnough(self.fullScreenImage.color.a, self.tgtAlpha, 0.001) then 
        self.isDirty = false
        self.fullScreenImage.color.a = self.tgtAlpha
        return
    end 

    local speed = self.approachSpeed * Time.deltaTime

    self.tmpColor.a = Mathf.Lerp( self.fullScreenImage.color.a, self.tgtAlpha, speed )
    self.fullScreenImage.color = self.tmpColor
end




-- ===============================================================


function DreamSpace_FullScreen:GetIsDirty()
    return self.isDirty
end

function DreamSpace_FullScreen:SwitchToBlack( approachSpeed_, immediately_ )
    if immediately_ == true then 
        self.tgtAlpha = 1.0 
        self.tmpColor.a = 1.0 
        self.fullScreenImage.color = self.tmpColor
        return
    end 

    self.approachSpeed = approachSpeed_
    self.tgtAlpha = 1.0
    self.isDirty = true
end


function DreamSpace_FullScreen:SwitchToTransparent( approachSpeed_, immediately_ )

    if immediately_ == true then 
        self.tgtAlpha = 0.0 
        self.tmpColor.a = 0.0 
        self.fullScreenImage.color = self.tmpColor
        return
    end 

    self.approachSpeed = approachSpeed_
    self.tgtAlpha = 0.0
    self.isDirty = true
end







return DreamSpace_FullScreen
